-- Campus Gigs - default seed data. Run after 01_schema.sql:
--     sudo mysql < db/02_seed.sql
-- Safe to run more than once: existing rows are kept and nothing is duplicated.
-- Do not edit this file once shared: add new reference data in db/changes/.

USE campus_gigs;

START TRANSACTION;

-- Platform settings (F12), read through SettingsService.
-- Re-running keeps any value the admin has changed since.
ON DUPLICATE KEY UPDATE setting_value = setting_value;

-- Default administrator. Admins have no wallet.
-- password_hash is produced by util.PasswordHasher:
-- pbkdf2$<iterations>$<saltBase64>$<hashBase64>. The password itself is shared in the group chat only.
     'pbkdf2$120000$BDx2sQpiIm9A/DoUUiqQBw==$O0dVGyrSkz+NvuSWeRkOLPEMDS045GZ4dVk0p5veM1o=',
     'ACTIVE');

-- Gig categories (F8). is_active defaults to TRUE.

-- Skills (F8), chosen by freelancers on their profile (F21) and attached to gigs.

COMMIT;
